import{z as B,x as A,o as s,c as d,q as t,j as i,D as E,d as l,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"seL4 形式验证","description":"","frontmatter":{"title":"seL4 形式验证","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/formal-verification-sel4.md","filePath":"cs/formal-verification-sel4.md","lastUpdated":1791063341000}'),p={name:"cs/formal-verification-sel4.md"};function f(m,a,c,h,C,u){const r=A("Mermaid");return s(),d("div",null,[a[2]||(a[2]=t('<h1 id="sel4-形式验证" tabindex="-1">seL4 形式验证 <a class="header-anchor" href="#sel4-形式验证" aria-label="Permalink to &quot;seL4 形式验证&quot;">​</a></h1><div class="epigraph"><p>seL4 把微内核的功能正确与完整性不变量做到机器可检查的证明：C 实现细化到抽象规格。它示范 TCB 小到可证，不示范「所有软件都应 Coq 一遍」。</p><footer>—— Klein et al., seL4: Formal Verification of an OS Kernel, SOSP 2009；后续完整性与时间隔离论文点名</footer></div><p>上一课<a href="/cs/sdl-lifecycle">SDL</a>是过程。安全进阶最后一课用 <strong>seL4</strong> 把 TCB 最小化接到<a href="/cs/proof-assistants">证明助手</a>的核：规格、细化、不变式。不重写 L4 IPC。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>普通内核太大不能证。seL4：抽象规格 ↔ Haskell 原型 ↔ C，证明细化与无用户到内核的完整性破坏（在模型内）。缺口是：证明排除的假设（硬件、汇编、编译器）仍要另管。</p><p><span class="marginnote">术语翻译「细化」：把高层的每一步承诺逐级替换成更低层的实现，并证明每一级行为一致——像把「帮我把文件存盘」这句话先落实成「写入这些扇区」，再落实成一串具体指令，每一层都要证明意思没有走样。seL4 的证明就是这种逐级对齐做到机器可检查。</span></p><h3 id="不是万能内核" tabindex="-1">不是万能内核 <a class="header-anchor" href="#不是万能内核" aria-label="Permalink to &quot;不是万能内核&quot;">​</a></h3><p>设备驱动与用户态仍要隔离策略。证明的是核，不是整个产品。</p><p><span class="marginnote">直觉类比：信任基（TCB）像城堡最内层的堡垒——墙越短越容易守。seL4 把「必须无条件信任的代码」压缩到约一万行 C；这堵墙短到可以逐块砖检查，而传统内核几千万行代码的墙，连数清砖都不可能。</span></p><p><span class="marginnote">Klein et al. SOSP 2009。对照本课程开头 Shannon：一端是信息论极限，一端是可证微内核。中间是合同与误用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>陈述细化链。指出时间隔离后续工作。课程封口：后课若有附录不插入主干。</p>',13)),(s(),i(n,null,{default:E(()=>[o(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E6%8A%BD%E8%B1%A1%E8%A7%84%E6%A0%BC%22%5D%20--%3E%20REF%5B%22%E7%BB%86%E5%8C%96%E8%AF%81%E6%98%8E%22%5D%0A%20%20REF%20--%3E%20C%5B%22C%20%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20ASSUME%5B%22%E7%A1%AC%E4%BB%B6%E4%B8%8E%E7%BC%96%E8%AF%91%E5%99%A8%E5%81%87%E8%AE%BE%22%5D%20--%3E%20LIM%5B%22%E8%AF%81%E6%98%8E%E8%BE%B9%E7%95%8C%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"形式方法服务最小 TCB。安全进阶从一次一密走到可证内核：保密极限、计算合同、协议绑定、内存完整、观测响应、隐私预算、组织过程，最后证明核。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者以为「形式验证过的内核就没有 bug」。实际上证明只在模型内成立——定理说的是「这份 C 代码细化了这个规格」；编译器有没有 bug、硬件有没有勘误、汇编启动代码对不对，都在证明范围之外，仍要靠工程手段兜底。")],-1)),(s(),i(n,null,{default:E(()=>[o(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROV%5B%22%E8%AF%81%E6%98%8E%E8%8C%83%E5%9B%B4%E5%86%85%3AseL4%20%E6%A0%B8%2C%E7%BA%A6%E4%B8%80%E4%B8%87%E8%A1%8C%20C%22%5D%20--%3E%20G1%5B%22%E7%94%A8%E6%88%B7%E8%BF%9B%E7%A8%8B%E7%9B%B8%E4%BA%92%E9%9A%94%E7%A6%BB%22%5D%0A%20%20PROV%20--%3E%20G2%5B%22%E5%AE%8C%E6%95%B4%E6%80%A7%E4%B8%8D%E5%8F%98%E9%87%8F%E6%A8%A1%E5%9E%8B%E5%86%85%E6%88%90%E7%AB%8B%22%5D%0A%20%20OUT1%5B%22%E8%AE%BE%E5%A4%87%E9%A9%B1%E5%8A%A8%22%5D%20--%3E%20OUT%5B%22%E8%AF%81%E6%98%8E%E4%B9%8B%E5%A4%96%22%5D%0A%20%20OUT2%5B%22%E7%BC%96%E8%AF%91%E5%99%A8%E4%B8%8E%E6%B1%87%E7%BC%96%E5%90%AF%E5%8A%A8%E7%A0%81%22%5D%20--%3E%20OUT%0A%20%20OUT3%5B%22%E7%A1%AC%E4%BB%B6%20errata%20%E4%B8%8E%E6%97%B6%E9%92%9F%22%5D%20--%3E%20OUT%0A%20%20OUT%20--%3E%20RES%5B%22%E9%9D%A0%E9%9A%94%E7%A6%BB%E7%AD%96%E7%95%A5%2F%E6%B5%8B%E8%AF%95%2F%E5%86%97%E4%BD%99%E5%85%9C%E5%BA%95%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 seL4 当所有系统的必换内核。安全进阶课程到此结束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SDL 是过程；seL4 是可证的最小核实例。</li><li>细化把规格接到 C；假设外仍要工程。</li><li>与开篇 Shannon 对照：极限、合同、可证 TCB。</li><li>安全进阶封口；证明助手课的核在此落地。</li><li>出处：Klein et al., SOSP 2009；对照 Shannon, 1949；<a href="/cs/proof-assistants">proof-assistants</a>。</li></ul>',4))])}const D=B(p,[["render",f]]);export{S as __pageData,D as default};
